using System;
using System.Collections.Generic;
using System.Text;
using MRes;
using UnityEngine;

namespace MarblesECS
{
    /// <summary>Opaque copies of raw .mres files, generated by the editor for Resources/Player builds.</summary>
    public sealed class DeviceResourceCatalog : ScriptableObject
    {
        [Serializable] public sealed class Entry { public string File; public byte[] Bytes; }
        public Entry[] Entries = Array.Empty<Entry>();
        public MResShaderRegistry Shaders;
        private Dictionary<uint, DeviceResource> resources;
        private static DeviceResourceCatalog current;
        public static DeviceResourceCatalog Current
        {
            get
            {
                if (current == null) current = Resources.Load<DeviceResourceCatalog>("Devices/DeviceCatalog");
                if (current == null) throw new InvalidOperationException("Missing Resources/Devices/DeviceCatalog.asset. Rebuild the MRes device catalog in the editor.");
                current.EnsureLoaded(); return current;
            }
        }
        public void Invalidate() { resources = null; }
        private void EnsureLoaded()
        {
            if (resources != null) return;
            var result = new Dictionary<uint, DeviceResource>();
            foreach (var entry in Entries)
            {
                try
                {
                    var package = MResLoader.Read(entry.Bytes);
                    if (package.Metadata.type != MResItemType.Device || string.IsNullOrWhiteSpace(package.LuaSource))
                        throw new ArgumentException("A device package needs device metadata and Lua behaviour.");
                    var definition = JsonUtility.FromJson<DeviceDefinition>(Encoding.UTF8.GetString(package.GetBytes("game/device.json")));
                    if (definition == null) throw new ArgumentException("Missing game/device.json.");
                    definition.Name = package.Metadata.name; definition.Description = package.Metadata.description;
                    if (package.Metadata.value != Math.Truncate(package.Metadata.value)) throw new ArgumentException("Device metadata.value must be an integer price.");
                    definition.Price = checked((long)package.Metadata.value);
                    definition.Validate();
                    if (result.ContainsKey(definition.Id)) throw new ArgumentException("Duplicate device ID " + definition.Id);
                    result.Add(definition.Id, new DeviceResource(package, definition));
                }
                catch (Exception e) { throw new InvalidOperationException("Invalid device package: " + entry.File, e); }
            }
            if (result.Count == 0) throw new InvalidOperationException("Resources/Devices has no device packages.");
            resources = result;
        }
        public DeviceResource Get(uint id)
        {
            EnsureLoaded();
            if (!resources.TryGetValue(id, out var result)) throw new ArgumentException("No MRes device with ID " + id);
            return result;
        }
        public DeviceDefinition[] Definitions()
        {
            EnsureLoaded(); var ids = new List<uint>(resources.Keys); ids.Sort();
            return ids.ConvertAll(id => resources[id].Definition.Copy()).ToArray();
        }
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetCache() { if (current != null) current.Invalidate(); current = null; }
    }
    public sealed class DeviceResource
    {
        public MResPackage Package { get; }
        public DeviceDefinition Definition { get; }
        internal DeviceResource(MResPackage package, DeviceDefinition definition) { Package = package; Definition = definition; }
    }
}
